+}
+.product-name a {
+  font-size: .95rem;
+  font-weight: 600;
+  color: var(--color-text);
+  line-height: 1.3;
+  text-decoration: none;
+}
+.product-name a:hover,
+.product-name a:focus-visible {
+  color: var(--color-brand);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .35rem;
+  margin-top: .4rem;
+  font-size: .78rem;
+  color: var(--color-text-muted);
+}
+.stars { color: var(--color-accent); letter-spacing: .05em; }
+
+.product-price-row {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  margin-top: auto;
+  padding-top: .75rem;
+}
+.price-current {
+  font-size: 1.1rem;
+  font-weight: 700;
+  color: var(--color-brand);
+}
+.price-original {
