  background: #0d1b2a;
  color: rgba(255,255,255,.7);
  padding: 3rem 0 1.5rem;
}
.footer-top {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 2rem 3rem;
  margin-bottom: 2.5rem;
}
.footer-brand .logo-text { color: #fff; }
.footer-brand p {
  margin-top: .75rem;
  font-size: .82rem;
  line-height: 1.7;
  max-width: 32ch;
}
.footer-socials {
  display: flex;
  gap: .5rem;
  margin-top: 1.25rem;
}
.social-btn {
  width: 34px; height: 34px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255,255,255,.15);
  background: transparent;
  color: rgba(255,255,255,.65);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .8rem;
  font-weight: 700;
  text-decoration: none;
  transition: border-color .12s, color .12s;
}
.social-btn:hover,
.social-btn:focus-visible {
  border-color: var(--color-accent);
  color: var(--color-accent);
}
.footer-col h3 {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 1rem;
}
.footer-col ul { display: flex; flex-direction: column; gap: .5rem; }
.footer-col a {
  font-size: .83rem;
  color: rgba(255,255,255,.6);
  text-decoration: none;
  transition: color .12s;
}
.footer-col a:hover,
.footer-col a:focus-visible { color: #fff; }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: .5rem 1rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255,255,255,.08);
  font-size: .78rem;
  color: rgba(255,255,255,.4);
}
.footer-bottom a {
  color: rgba(255,255,255,.5);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.footer-bottom a:hover,
.footer-bottom a:focus-visible { color: #fff; }

/* =========================================================
   Responsive
   ========================================================= */
@media (max-width: 900px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-hero-card { grid-row: span 1; min-height: 280px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .primary-nav { display: none; }
  .menu-toggle { display: flex; }
}

@media (max-width: 600px) {
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: .75rem; }
  .footer-top { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { border-radius: var(--radius-md); }
  .newsletter-form .btn { border-radius: var(--radius-md); }
  .deals-grid { grid-template-columns: 1fr; }
  .usp-list { grid-template-columns: 1fr 1fr; }
  .editorial-small { flex-direction: column; }
  .editorial-small-img { width: 100%; height: 120px; }
}

@media (max-width: 400px) {
  .product-grid { grid-template-columns: 1fr; }
}

/* Mobile nav drawer */
.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: none;
}
.mobile-nav.open { display: block; }
.mobile-nav-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.5);
}
.mobile-nav-panel {
  position: absolute;
  top: 0; left: 0; bottom: 0;
  width: min(320px, 90vw);
  background: var(--color-surface);
  padding: 1.5rem;
  overflow-y: auto;
  box-shadow: 4px 0 20px rgba(0,0,0,.2);
}
.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
}
.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: .25rem;
}
.mobile-nav-links a,
.mobile-nav-links button {
  display: block;
  width: 100%;
  text-align: left;
  padding: .75rem 1rem;
  border-radius: var(--radius-md);
  font-size: .95rem;
  font-weight: 500;
  color: var(--color-text);
  text-decoration: none;
  border: none;
  background: transparent;
  transition: background .1s;
}
.mobile-nav-links a:hover,
.mobile-nav-links button:hover,
.mobile-nav-links a:focus-visible,
.mobile-nav-links button:focus-visible { background: var(--color-bg); }
