+}
+.hero-img-tile {
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  background: rgba(255,255,255,.06);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.hero-img-tile:first-child {
+  grid-row: span 2;
+  border-radius: var(--radius-lg);
+}
+.hero-img-tile svg { opacity: .35; }
+
+/* =========================================================
+   Category pills strip
+   ========================================================= */
+.category-strip {
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  padding: 1.25rem 0;
+  overflow-x: auto;
+  -webkit-overflow-scrolling: touch;
+  scrollbar-width: none;
+}
+.category-strip::-webkit-scrollbar { display: none; }
+.category-list {
+  display: flex;
+  gap: .75rem;
+  padding-inline: var(--gutter);
+  max-width: var(--max-width);
+  margin-inline: auto;
+}
+.category-pill {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .4rem;
+  flex-shrink: 0;
+  text-decoration: none;
+  color: var(--color-text-muted);
+  font-size: .78rem;
+  font-weight: 600;
+  transition: color .12s;
+}
+.category-pill:hover,
+.category-pill:focus-visible { color: var(--color-brand); }
+.category-icon {
+  width: 52px;
+  height: 52px;
+  border-radius: var(--radius-lg);
+  background: var(--color-bg);
+  border: 2px solid var(--color-border);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.4rem;
+  transition: border-color .12s, background .12s;
+}
+.category-pill:hover .category-icon,
+.category-pill:focus-visible .category-icon {
+  border-color: var(--color-accent);
+  background: #fef3c7;
+}
+
+/* =========================================================
+   Product cards
+   ========================================================= */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.5rem;
+}
+
+.product-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  box-shadow: var(--shadow-card);
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow .2s, transform .2s;
+  border: 1px solid var(--color-border);
+}
+@media (prefers-reduced-motion: no-preference) {
+  .product-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-3px); }
+}
+
+.product-img-wrap {
+  aspect-ratio: 1;
+  overflow: hidden;
+  background: var(--color-bg);
+  position: relative;
+}
+.product-img-wrap img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform .3s;
+}
+@media (prefers-reduced-motion: no-preference) {
+  .product-card:hover .product-img-wrap img { transform: scale(1.04); }
+}
+
+/* Product badges */
+.product-badges {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .35rem;
+  pointer-events: none;
+}
+.badge {
+  display: inline-flex;
+  align-items: center;
+  padding: .2rem .55rem;
+  border-radius: var(--radius-pill);
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .04em;
+  text-transform: uppercase;
+}
+.badge-sale  { background: var(--color-sale);    color: #fff; }
+.badge-new   { background: var(--color-brand);   color: #fff; }
+.badge-trending { background: var(--color-accent); color: var(--color-brand); }
+
+/* Wishlist toggle on card */
+.wishlist-btn {
+  position: absolute;
+  top: .75rem; right: .75rem;
+  background: rgba(255,255,255,.9);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-pill);
+  width: 34px; height: 34px;
+  display: flex; align-items: center; justify-content: center;
+  color: var(--color-text-muted);
+  transition: color .12s, background .12s, border-color .12s;
+}
+.wishlist-btn:hover,
+.wishlist-btn:focus-visible {
+  color: var(--color-sale);
+  border-color: var(--color-sale);
+  background: #fff;
+}
+.wishlist-btn[aria-pressed="true"] { color: var(--color-sale); border-color: var(--color-sale); }
+
+.product-body {
+  padding: 1rem 1rem .5rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+.product-brand {
+  font-size: .72rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--color-text-muted);
+  margin-bottom: .25rem;
+}
+.product-name a {
+  font-size: .95rem;
+  font-weight: 600;
+  color: var(--color-text);
+  line-height: 1.3;
+  text-decoration: none;
+}
+.product-name a:hover,
+.product-name a:focus-visible {
+  color: var(--color-brand);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .35rem;
+  margin-top: .4rem;
+  font-size: .78rem;
+  color: var(--color-text-muted);
+}
+.stars { color: var(--color-accent); letter-spacing: .05em; }
+
+.product-price-row {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  margin-top: auto;
+  padding-top: .75rem;
+}
+.price-current {
+  font-size: 1.1rem;
+  font-weight: 700;
+  color: var(--color-brand);
+}
+.price-original {
+  font-size: .85rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.price-discount {
+  font-size: .75rem;
+  font-weight: 700;
+  color: var(--color-sale);
+}
+
+.product-footer {
+  padding: .75rem 1rem 1rem;
+  border-top: 1px solid var(--color-border);
+  margin-top: .25rem;
+}
+.btn-add-cart {
+  width: 100%;
+  padding: .6rem 1rem;
+  background: var(--color-brand);
+  color: #fff;
+  border: none;
+  border-radius: var(--radius-md);
+  font-size: .875rem;
+  font-weight: 600;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: .4rem;
+  transition: background .12s;
+}
+.btn-add-cart:hover,
+.btn-add-cart:focus-visible { background: var(--color-brand-light); }
+.btn-add-cart:active { transform: scale(.98); }
+
+/* =========================================================
+   Featured Products section
+   ========================================================= */
+.featured-products {
+  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
+}
+
+/* =========================================================
+   Deals section
+   ========================================================= */
+.deals-section {
+  background: #fff8ed;
+  border-top: 1px solid #fde68a;
+  border-bottom: 1px solid #fde68a;
+  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.deal-hero-card {
+  background: var(--color-brand);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  min-height: 380px;
+  position: relative;
+  grid-row: span 2;
+  color: #fff;
+  padding: 2rem;
+}
+.deal-hero-bg {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(160deg, #1e3a5f 0%, #0f1f30 100%);
+  z-index: 0;
+}
+.deal-hero-bg::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(circle at 70% 30%, rgba(245,158,11,.18), transparent 60%);
+}
+.deal-hero-content { position: relative; z-index: 1; }
+.deal-eyebrow {
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .5rem;
+}
+.deal-hero-card h3 {
+  font-size: clamp(1.3rem, 3vw, 1.8rem);
+  font-weight: 800;
+  line-height: 1.15;
+  letter-spacing: -.02em;
+  margin-bottom: .75rem;
+}
+.deal-hero-card p { color: rgba(255,255,255,.75); font-size: .9rem; margin-bottom: 1.25rem; }
+.deal-timer {
+  display: flex;
+  gap: .5rem;
+  margin-bottom: 1.5rem;
+}
+.timer-unit {
+  text-align: center;
+  background: rgba(255,255,255,.1);
+  border-radius: var(--radius-sm);
+  padding: .4rem .6rem;
+  min-width: 46px;
+}
+.timer-digits {
+  font-size: 1.3rem;
+  font-weight: 700;
+  display: block;
+  line-height: 1;
+}
+.timer-label {
+  font-size: .6rem;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  color: rgba(255,255,255,.6);
+}
+
+/* Smaller deal cards */
+.deal-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-lg);
+  border: 1px solid var(--color-border);
+  box-shadow: var(--shadow-card);
+  display: flex;
+  gap: 1rem;
+  padding: 1.25rem;
+  align-items: flex-start;
+  transition: box-shadow .2s;
+}
+@media (prefers-reduced-motion: no-preference) {
+  .deal-card:hover { box-shadow: var(--shadow-card-hover); }
+}
+.deal-card-img {
+  width: 90px;
+  height: 90px;
+  border-radius: var(--radius-md);
+  background: var(--color-bg);
+  overflow: hidden;
+  flex-shrink: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.deal-card-body { flex: 1; }
+.deal-card-name {
+  font-size: .9rem;
+  font-weight: 600;
+  color: var(--color-text);
+  margin-bottom: .2rem;
+  line-height: 1.3;
+}
+.deal-card-name a {
+  text-decoration: none;
+  color: inherit;
+}
+.deal-card-name a:hover,
+.deal-card-name a:focus-visible {
+  color: var(--color-brand);
+  text-decoration: underline;
+}
+.deal-card-prices {
+  display: flex;
+  align-items: baseline;
+  gap: .4rem;
+  margin-bottom: .5rem;
+}
+.deal-progress-label {
+  font-size: .72rem;
+  color: var(--color-text-muted);
+  margin-bottom: .25rem;
+}
+.deal-progress {
+  height: 5px;
+  background: var(--color-border);
+  border-radius: var(--radius-pill);
+  overflow: hidden;
+}
+.deal-progress-bar {
+  height: 100%;
+  background: var(--color-accent-dark);
+  border-radius: var(--radius-pill);
+  transition: width .3s;
+}
+
+/* =========================================================
+   Brand editorial strip
+   ========================================================= */
+.brand-strip {
+  padding: 2rem 0;
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+}
+.brand-strip-inner {
+  display: flex;
+  align-items: center;
+  gap: 2rem;
+  flex-wrap: wrap;
+}
+.brand-strip-heading {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-text-muted);
+  flex-shrink: 0;
+  white-space: nowrap;
+}
+.brand-logos {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 1.5rem 2.5rem;
+  align-items: center;
+}
+.brand-logo {
+  font-size: .95rem;
+  font-weight: 800;
+  letter-spacing: -.04em;
+  color: var(--color-border);
+  transition: color .15s;
+  text-decoration: none;
+}
+.brand-logo:hover,
+.brand-logo:focus-visible { color: var(--color-brand); }
+
+/* =========================================================
+   Editorial section
+   ========================================================= */
+.editorial-section {
+  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
+}
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr;
+  gap: 1.5rem;
+}
+.editorial-side { display: flex; flex-direction: column; gap: 1.5rem; }
+
+.editorial-card {
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  position: relative;
+  display: block;
+  text-decoration: none;
+  color: inherit;
+}
+.editorial-card-img {
+  aspect-ratio: 16/9;
+  background: var(--color-brand);
+  overflow: hidden;
+  position: relative;
+}
+.editorial-card.featured .editorial-card-img { aspect-ratio: 3/2; }
+.editorial-card-img-inner {
+  width: 100%;
+  height: 100%;
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.editorial-card-overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(15,25,40,.85) 0%, rgba(15,25,40,.1) 60%, transparent 100%);
+  z-index: 1;
+}
+.editorial-card-content {
+  position: absolute;
+  bottom: 0; left: 0; right: 0;
+  z-index: 2;
+  padding: 1.5rem;
+  color: #fff;
+}
+.editorial-category {
+  font-size: .68rem;
+  font-weight: 700;
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  display: block;
+  margin-bottom: .4rem;
+}
+.editorial-card h3 {
+  font-size: clamp(.95rem, 2vw, 1.25rem);
+  font-weight: 700;
+  line-height: 1.25;
+  letter-spacing: -.01em;
+  margin-bottom: .4rem;
+}
+.editorial-card.featured h3 { font-size: clamp(1.2rem, 3vw, 1.7rem); }
+.editorial-excerpt {
+  font-size: .82rem;
+  color: rgba(255,255,255,.75);
+  line-height: 1.5;
+  display: -webkit-box;
+  -webkit-line-clamp: 2;
+  -webkit-box-orient: vertical;
+  overflow: hidden;
+}
+.editorial-card:hover .editorial-card-img-inner,
+.editorial-card:focus-visible .editorial-card-img-inner {
+  transform: scale(1.03);
+}
+@media (prefers-reduced-motion: no-preference) {
+  .editorial-card-img-inner { transition: transform .4s; }
+}
+.editorial-card:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 3px; }
+
+/* Side editorial small cards */
+.editorial-small {
+  display: flex;
+  gap: 1rem;
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  text-decoration: none;
+  color: inherit;
+  transition: box-shadow .2s;
+  box-shadow: var(--shadow-card);
+}
+@media (prefers-reduced-motion: no-preference) {
+  .editorial-small:hover { box-shadow: var(--shadow-card-hover); }
+}
+.editorial-small:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 3px; }
+.editorial-small-img {
+  width: 110px;
+  flex-shrink: 0;
+  background: var(--color-bg);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  overflow: hidden;
+}
+.editorial-small-body {
+  padding: 1rem;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+}
+.editorial-small-body .editorial-category { color: var(--color-accent-dark); }
+.editorial-small h3 {
+  font-size: .88rem;
+  font-weight: 600;
+  line-height: 1.3;
+  color: var(--color-text);
+  margin-bottom: .25rem;
+}
+.editorial-small time {
+  font-size: .72rem;
+  color: var(--color-text-muted);
+}
+
+/* =========================================================
+   USP strip (trust badges)
+   ========================================================= */
+.usp-strip {
+  background: var(--color-brand);
+  color: rgba(255,255,255,.9);
+  padding: 2rem 0;
+}
+.usp-list {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
+  gap: 1.5rem;
+}
+.usp-item {
+  display: flex;
+  align-items: flex-start;
+  gap: .75rem;
+}
+.usp-icon {
+  font-size: 1.5rem;
+  flex-shrink: 0;
+  margin-top: .1rem;
+}
+.usp-item strong {
+  display: block;
+  font-size: .9rem;
+  font-weight: 700;
+  color: #fff;
+  margin-bottom: .1rem;
+}
+.usp-item span { font-size: .8rem; color: rgba(255,255,255,.65); }
+
+/* =========================================================
+   Newsletter
+   ========================================================= */
+.newsletter-section {
+  padding: clamp(2.5rem, 6vw, 4rem) 0;
+  background: var(--color-surface);
+  border-top: 1px solid var(--color-border);
+}
+.newsletter-inner {
+  max-width: 560px;
+  margin-inline: auto;
+  text-align: center;
+}
+.newsletter-inner h2 {
+  font-size: clamp(1.3rem, 3vw, 1.8rem);
+  font-weight: 700;
+  letter-spacing: -.02em;
+  color: var(--color-brand);
+  margin-bottom: .5rem;
+}
+.newsletter-inner p {
+  color: var(--color-text-muted);
+  font-size: .9rem;
+  margin-bottom: 1.5rem;
+}
+.newsletter-form {
+  display: flex;
+  gap: .5rem;
+  max-width: 420px;
+  margin-inline: auto;
+}
+.newsletter-form label { /* visually hidden but present */ }
+.newsletter-input {
+  flex: 1;
+  padding: .7rem 1rem;
+  border: 2px solid var(--color-border);
+  border-radius: var(--radius-pill);
+  font-size: .9rem;
+  font-family: inherit;
+  background: var(--color-bg);
+  color: var(--color-text);
+  outline: none;
+  transition: border-color .15s;
+}
+.newsletter-input:focus {
+  border-color: var(--color-brand);
+  background: #fff;
+}
+.newsletter-status {
+  margin-top: .75rem;
+  font-size: .85rem;
+  min-height: 1.4em;
+}
+.newsletter-status[data-state="success"] { color: var(--color-success); }
+.newsletter-status[data-state="error"]   { color: var(--color-sale); }
+
+/* =========================================================
+   Footer
+   ========================================================= */
+.site-footer {
+  background: #0d1b2a;
+  color: rgba(255,255,255,.7);
+  padding: 3rem 0 1.5rem;
+}
+.footer-top {
+  display: grid;
+  grid-template-columns: 2fr repeat(3, 1fr);
+  gap: 2rem 3rem;
+  margin-bottom: 2.5rem;
+}
+.footer-brand .logo-text { color: #fff; }
+.footer-brand p {
+  margin-top: .75rem;
+  font-size: .82rem;
+  line-height: 1.7;
+  max-width: 32ch;
+}
+.footer-socials {
+  display: flex;
+  gap: .5rem;
+  margin-top: 1.25rem;
+}
+.social-btn {
+  width: 34px; height: 34px;
+  border-radius: var(--radius-md);
+  border: 1px solid rgba(255,255,255,.15);
+  background: transparent;
+  color: rgba(255,255,255,.65);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: .8rem;
+  font-weight: 700;
+  text-decoration: none;
+  transition: border-color .12s, color .12s;
+}
+.social-btn:hover,
+.social-btn:focus-visible {
+  border-color: var(--color-accent);
+  color: var(--color-accent);
+}
+.footer-col h3 {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: #fff;
+  margin-bottom: 1rem;
+}
+.footer-col ul { display: flex; flex-direction: column; gap: .5rem; }
+.footer-col a {
+  font-size: .83rem;
+  color: rgba(255,255,255,.6);
+  text-decoration: none;
+  transition: color .12s;
+}
+.footer-col a:hover,
+.footer-col a:focus-visible { color: #fff; }
+
+.footer-bottom {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: .5rem 1rem;
+  padding-top: 1.5rem;
+  border-top: 1px solid rgba(255,255,255,.08);
+  font-size: .78rem;
+  color: rgba(255,255,255,.4);
+}
+.footer-bottom a {
+  color: rgba(255,255,255,.5);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+.footer-bottom a:hover,
+.footer-bottom a:focus-visible { color: #fff; }
+
+/* =========================================================
+   Responsive
+   ========================================================= */
+@media (max-width: 900px) {
+  .hero-inner { grid-template-columns: 1fr; }
+  .hero-visual { display: none; }
+  .deals-grid { grid-template-columns: 1fr; }
+  .deal-hero-card { grid-row: span 1; min-height: 280px; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .footer-top { grid-template-columns: 1fr 1fr; }
+  .primary-nav { display: none; }
+  .menu-toggle { display: flex; }
+}
+
+@media (max-width: 600px) {
+  .product-grid { grid-template-columns: repeat(2, 1fr); gap: .75rem; }
+  .footer-top { grid-template-columns: 1fr; }
+  .newsletter-form { flex-direction: column; }
+  .newsletter-input { border-radius: var(--radius-md); }
+  .newsletter-form .btn { border-radius: var(--radius-md); }
+  .deals-grid { grid-template-columns: 1fr; }
+  .usp-list { grid-template-columns: 1fr 1fr; }
+  .editorial-small { flex-direction: column; }
+  .editorial-small-img { width: 100%; height: 120px; }
+}
+
+@media (max-width: 400px) {
+  .product-grid { grid-template-columns: 1fr; }
+}
+
+/* Mobile nav drawer */
+.mobile-nav {
+  position: fixed;
+  inset: 0;
+  z-index: 300;
