+.header-utils .btn-icon:hover,
+.header-utils .btn-icon:focus-visible {
+  background: rgba(255,255,255,.12);
+  color: #fff;
+}
+.icon-badge { background: var(--color-accent); color: var(--color-brand); }
+
+/* Mobile menu toggle (shown on small screens) */
+.menu-toggle { display: none; }
+
+/* =========================================================
+   Promo banner
+   ========================================================= */
+.promo-banner {
+  background: var(--color-accent);
+  color: var(--color-brand);
+  text-align: center;
+  padding: .5rem var(--gutter);
