+}
+.btn-add-cart:hover,
+.btn-add-cart:focus-visible { background: var(--color-brand-light); }
+.btn-add-cart:active { transform: scale(.98); }
+
+/* =========================================================
+   Featured Products section
+   ========================================================= */
+.featured-products {
+  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
+}
+
+/* =========================================================
+   Deals section
+   ========================================================= */
+.deals-section {
+  background: #fff8ed;
+  border-top: 1px solid #fde68a;
+  border-bottom: 1px solid #fde68a;
+  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.deal-hero-card {
+  background: var(--color-brand);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  justify-content: flex-end;
+  min-height: 380px;
+  position: relative;
+  grid-row: span 2;
+  color: #fff;
+  padding: 2rem;
+}
+.deal-hero-bg {
+  position: absolute;
+  inset: 0;
