+.deal-hero-bg::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(circle at 70% 30%, rgba(245,158,11,.18), transparent 60%);
+}
+.deal-hero-content { position: relative; z-index: 1; }
+.deal-eyebrow {
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .5rem;
+}
+.deal-hero-card h3 {
+  font-size: clamp(1.3rem, 3vw, 1.8rem);
