+   Footer
+   ========================================================= */
+.site-footer {
+  background: #0d1b2a;
+  color: rgba(255,255,255,.7);
+  padding: 3rem 0 1.5rem;
+}
+.footer-top {
+  display: grid;
+  grid-template-columns: 2fr repeat(3, 1fr);
+  gap: 2rem 3rem;
+  margin-bottom: 2.5rem;
+}
+.footer-brand .logo-text { color: #fff; }
+.footer-brand p {
+  margin-top: .75rem;
+  font-size: .82rem;
+  line-height: 1.7;
+  max-width: 32ch;
+}
+.footer-socials {
+  display: flex;
+  gap: .5rem;
+  margin-top: 1.25rem;
+}
+.social-btn {
+  width: 34px; height: 34px;
