  const promoBanner = document.getElementById('promo-banner');
  const promoClose  = document.getElementById('promo-close');
  if (promoClose && promoBanner) {
    promoClose.addEventListener('click', () => {
      promoBanner.hidden = true;
      // move focus to skip link or first interactive element in header
      const firstFocus = document.querySelector('.site-header a, .site-header button');
      if (firstFocus) firstFocus.focus();
    });
  }

  // ── Mobile nav toggle ─────────────────────────────────
  const menuToggle   = document.getElementById('menu-toggle');
  const mobileNav    = document.getElementById('mobile-nav');
  const mobileClose  = document.getElementById('mobile-nav-close');
  const mobileBackdrop = document.getElementById('mobile-nav-backdrop');

  function openMobileNav() {
    mobileNav.classList.add('open');
    mobileNav.removeAttribute('hidden');
    menuToggle.setAttribute('aria-expanded', 'true');
    mobileClose.focus();
    document.body.style.overflow = 'hidden';
  }

  function closeMobileNav() {
    mobileNav.classList.remove('open');
    mobileNav.setAttribute('hidden', '');
    menuToggle.setAttribute('aria-expanded', 'false');
    menuToggle.focus();
    document.body.style.overflow = '';
  }

  if (menuToggle) {
    menuToggle.addEventListener('click', openMobileNav);
  }
  if (mobileClose) {
    mobileClose.addEventListener('click', closeMobileNav);
  }
  if (mobileBackdrop) {
    mobileBackdrop.addEventListener('click', closeMobileNav);
  }
  // Escape key closes mobile nav
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && mobileNav && mobileNav.classList.contains('open')) {
      closeMobileNav();
    }
  });

  // ── Expandable desktop nav items ─────────────────────
  const expandBtns = document.querySelectorAll('.nav-expand-btn');
  expandBtns.forEach((btn) => {
    const subNav = btn.nextElementSibling;
    btn.addEventListener('click', () => {
      const expanded = btn.getAttribute('aria-expanded') === 'true';
      // Close all others
      expandBtns.forEach((b) => {
        b.setAttribute('aria-expanded', 'false');
        if (b.nextElementSibling) b.nextElementSibling.hidden = true;
      });
      if (!expanded) {
        btn.setAttribute('aria-expanded', 'true');
        subNav.hidden = false;
        // focus first link
        const firstLink = subNav.querySelector('a');
        if (firstLink) firstLink.focus();
      }
    });
    // Escape closes this sub-nav
    if (subNav) {
      subNav.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          btn.setAttribute('aria-expanded', 'false');
          subNav.hidden = true;
          btn.focus();
        }
      });
    }
  });

  // Close expandable navs when clicking outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.nav-item-expandable')) {
      expandBtns.forEach((btn) => {
        btn.setAttribute('aria-expanded', 'false');
        if (btn.nextElementSibling) btn.nextElementSibling.hidden = true;
      });
    }
  });

  // ── Wishlist toggle ───────────────────────────────────
  document.querySelectorAll('.wishlist-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const pressed = btn.getAttribute('aria-pressed') === 'true';
      btn.setAttribute('aria-pressed', String(!pressed));
      const productName = btn.dataset.product || 'item';
      btn.setAttribute('aria-label', !pressed
        ? `Remove ${productName} from wishlist`
        : `Add ${productName} to wishlist`);
      announceStatus(!pressed
        ? `${productName} added to wishlist`
        : `${productName} removed from wishlist`);
    });
  });

  // ── Add to cart ───────────────────────────────────────
  document.querySelectorAll('.btn-add-cart').forEach((btn) => {
    btn.addEventListener('click', () => {
      const label = btn.getAttribute('aria-label') || '';
      const match = label.match(/Add to cart: (.+)/);
      const name  = match ? match[1] : 'Item';

      // Update cart count badge
      const cartBadge = document.getElementById('cart-count');
      if (cartBadge) {
        const current = parseInt(cartBadge.textContent, 10) || 0;
        cartBadge.textContent = current + 1;
        // Update the cart button's accessible label
        const cartBtn = document.getElementById('cart-btn');
        if (cartBtn) {
          cartBtn.setAttribute('aria-label', `Cart, ${current + 1} item${current + 1 !== 1 ? 's' : ''}`);
        }
      }

      // Temporary feedback on button
      const original = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = `<svg aria-hidden="true" width="15" height="15" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clip-rule="evenodd"/></svg> Added!`;
      setTimeout(() => {
        btn.disabled = false;
        btn.innerHTML = original;
      }, 1800);

      announceStatus(`${name} added to cart`);
    });
  });

  // ── Polite live region announcer ─────────────────────
  let liveRegion = document.getElementById('live-region');
  if (!liveRegion) {
    liveRegion = document.createElement('div');
    liveRegion.id = 'live-region';
    liveRegion.setAttribute('aria-live', 'polite');
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.className = 'sr-only';
    document.body.appendChild(liveRegion);
  }
  function announceStatus(msg) {
    liveRegion.textContent = '';
    // Tiny delay ensures AT re-reads even duplicate messages
    requestAnimationFrame(() => { liveRegion.textContent = msg; });
  }

  // ── Countdown timer ───────────────────────────────────
  const timerEls = {
    h: document.getElementById('timer-h'),
    m: document.getElementById('timer-m'),
    s: document.getElementById('timer-s'),
  };
  if (timerEls.h && timerEls.m && timerEls.s) {
    // End time: 5 hours from page load
    const endTime = Date.now() + (5 * 60 * 60 * 1000);
    function updateTimer() {
      const diff = Math.max(0, endTime - Date.now());
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      timerEls.h.textContent = String(h).padStart(2, '0');
      timerEls.m.textContent = String(m).padStart(2, '0');
      timerEls.s.textContent = String(s).padStart(2, '0');
    }
    updateTimer();
    setInterval(updateTimer, 1000);
  }

  // ── Newsletter form ───────────────────────────────────
  const newsletterForm   = document.getElementById('newsletter-form');
  const newsletterStatus = document.getElementById('newsletter-status');
  if (newsletterForm && newsletterStatus) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = newsletterForm.querySelector('input[type="email"]');
      if (!input.value.trim()) {
        newsletterStatus.textContent = 'Please enter a valid email address.';
        newsletterStatus.dataset.state = 'error';
        input.focus();
        return;
      }
      // Simulate async submit
      const submitBtn = newsletterForm.querySelector('button[type="submit"]');
      submitBtn.disabled = true;
      submitBtn.textContent = 'Subscribing…';
      setTimeout(() => {
        newsletterStatus.textContent = '✓ You\'re subscribed! Check your inbox for a welcome offer.';
        newsletterStatus.dataset.state = 'success';
        input.value = '';
        submitBtn.disabled = false;
        submitBtn.textContent = 'Subscribe';
        announceStatus('Successfully subscribed to LUMA newsletter');
      }, 900);
    });
  }
})();
