          html: n.html.slice(0, 200),
          failureSummary: n.failureSummary
        }))
      })),
      bp: bp.map(v => ({
        id: v.id,
        impact: v.impact,
        nodes: v.nodes.map(n => ({
          target: n.target,
          html: n.html.slice(0, 150)
        }))
      }))
    };

    process.stdout.write(JSON.stringify(out, null, 2) + '\n');
    process.exit(wcag.length > 0 ? 1 : 0);
  } catch (e) {
    console.error(e);
    process.exit(2);
  }
})();
