  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; height: auto; }
ul, ol { list-style: none; }
a { color: inherit; text-decoration: none; }
/* Override UA a:link / a:visited pseudo-class colors so component rules cascade correctly */
a:link, a:visited { color: inherit; }
button { cursor: pointer; font: inherit; }

/* --- Forced colors ---------------------------------------- */
@media (forced-colors: active) {
  .card { border: 1px solid ButtonText; }
  .btn-primary, .btn-outline { border: 2px solid ButtonText; }
  .badge { border: 1px solid ButtonText; }
}

/* =========================================================
   Skip link
   ========================================================= */
.skip-link {
  position: absolute;
  top: 0; left: 0;
  background: var(--color-brand);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: 0 0 var(--radius-md) 0;
  font-weight: 600;
  z-index: 9999;
  transform: translateY(-100%);
  transition: transform .15s;
}
.skip-link:focus { transform: translateY(0); }

/* =========================================================
   Utilities
   ========================================================= */
.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.container {
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-header h2 {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-brand);
}
.section-header .view-all {
  font-size: .875rem;
  font-weight: 600;
  color: #92400e;
  text-decoration: underline;
  text-underline-offset: 3px;
  white-space: nowrap;
}
.section-header .view-all:hover,
.section-header .view-all:focus-visible { color: var(--color-brand); }

/* Focus ring */
:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* =========================================================
   Buttons
   ========================================================= */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .65rem 1.5rem;
  border-radius: var(--radius-pill);
  font-size: .9rem;
  font-weight: 600;
  border: 2px solid transparent;
  transition: background .15s, color .15s, border-color .15s, transform .1s;
  line-height: 1.2;
  white-space: nowrap;
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--color-brand);
  color: #fff;
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--color-brand-light);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-brand);
}
.btn-accent:hover, .btn-accent:focus-visible {
  background: var(--color-accent-dark);
  color: #fff;
}

.btn-outline {
  background: transparent;
  color: var(--color-brand);
  border-color: var(--color-brand);
}
.btn-outline:hover, .btn-outline:focus-visible {
  background: var(--color-brand);
  color: #fff;
}

.btn-ghost {
  background: transparent;
  color: var(--color-brand);
  padding-inline: .5rem;
}
.btn-ghost:hover, .btn-ghost:focus-visible {
  background: var(--color-border);
  border-radius: var(--radius-md);
}

/* Icon button */
.btn-icon {
  background: transparent;
  border: none;
  padding: .5rem;
  border-radius: var(--radius-md);
  color: var(--color-brand);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.btn-icon:hover, .btn-icon:focus-visible { background: var(--color-border); }

/* Badge on icon buttons */
.icon-badge {
  position: absolute;
  top: 2px; right: 2px;
  background: var(--color-accent);
  color: var(--color-brand);
  font-size: .6rem;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: var(--radius-pill);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 3px;
  line-height: 1;
}

/* =========================================================
   Site Header
   ========================================================= */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-brand);
  color: #fff;
  height: var(--nav-height);
  box-shadow: 0 2px 12px rgba(0,0,0,.2);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  height: 100%;
  padding-inline: var(--gutter);
  max-width: var(--max-width);
  margin-inline: auto;
}

/* Logo */
.logo-link {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-mark {
  width: 36px;
  height: 36px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  font-weight: 900;
  color: var(--color-brand);
  font-style: italic;
}
.logo-text {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: #fff;
}

/* Primary nav */
.primary-nav {
  flex: 1;
  display: flex;
  align-items: center;
}
.primary-nav ul {
  display: flex;
  align-items: center;
  gap: .25rem;
}
.primary-nav a {
  display: block;
  padding: .5rem .875rem;
  font-size: .9rem;
  font-weight: 500;
  color: rgba(255,255,255,.82);
  border-radius: var(--radius-md);
  transition: color .12s, background .12s;
}
.primary-nav a:hover,
.primary-nav a:focus-visible {
  color: #fff;
  background: rgba(255,255,255,.1);
}
.primary-nav a[aria-current="page"] {
  color: var(--color-accent);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Expandable nav item */
.nav-item-expandable {
  position: relative;
}
.nav-expand-btn {
  background: transparent;
  border: none;
  display: flex;
  align-items: center;
  gap: .3rem;
  padding: .5rem .875rem;
  font-size: .9rem;
  font-weight: 500;
  color: rgba(255,255,255,.82);
  border-radius: var(--radius-md);
  transition: color .12s, background .12s;
}
.nav-expand-btn:hover,
.nav-expand-btn:focus-visible {
  color: #fff;
  background: rgba(255,255,255,.1);
}
.nav-expand-btn .chevron {
  width: 14px;
  height: 14px;
  transition: transform .2s;
}
.nav-expand-btn[aria-expanded="true"] .chevron { transform: rotate(180deg); }
.nav-sub {
  position: absolute;
  top: calc(100% + .5rem);
  left: 0;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card-hover);
  min-width: 180px;
  z-index: 200;
}
.nav-sub[hidden] { display: none; }
.nav-sub li a {
  display: block;
  padding: .6rem 1rem;
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text);
  border-radius: 0;
  transition: background .1s;
}
.nav-sub li:first-child a { border-radius: var(--radius-md) var(--radius-md) 0 0; }
.nav-sub li:last-child a  { border-radius: 0 0 var(--radius-md) var(--radius-md); }
.nav-sub li a:hover,
.nav-sub li a:focus-visible {
  background: var(--color-bg);
  color: var(--color-brand);
}

/* Header utilities */
.header-utils {
  display: flex;
  align-items: center;
  gap: .25rem;
  flex-shrink: 0;
}
.header-utils .btn-icon { color: rgba(255,255,255,.85); }
.header-utils .btn-icon:hover,
.header-utils .btn-icon:focus-visible {
  background: rgba(255,255,255,.12);
  color: #fff;
}
.icon-badge { background: var(--color-accent); color: var(--color-brand); }

/* Mobile menu toggle (shown on small screens) */
.menu-toggle { display: none; }

/* =========================================================
   Promo banner
   ========================================================= */
.promo-banner {
  background: var(--color-accent);
  color: var(--color-brand);
  text-align: center;
  padding: .5rem var(--gutter);
  font-size: .85rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  position: relative;
}
.promo-banner p { flex: 1; text-align: center; }
.promo-banner .promo-close {
  background: transparent;
  border: none;
  font-size: 1.1rem;
  line-height: 1;
  color: var(--color-brand);
  cursor: pointer;
  padding: .25rem .5rem;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}
.promo-banner .promo-close:hover,
.promo-banner .promo-close:focus-visible { background: rgba(0,0,0,.08); }
.promo-banner[hidden] { display: none; }

/* =========================================================
   Hero
   ========================================================= */
.hero {
  background: var(--color-brand);
  color: #fff;
  padding: clamp(3rem, 8vw, 6rem) 0;
  overflow: hidden;
  position: relative;
}
.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 80% 50%, rgba(245,158,11,.12), transparent);
  pointer-events: none;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
  position: relative;
  z-index: 1;
}
.hero-eyebrow {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .75rem;
}
.hero h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}
.hero h1 em {
  font-style: normal;
  color: var(--color-accent);
  display: block;
}
.hero-desc {
  font-size: clamp(.95rem, 2vw, 1.1rem);
  color: rgba(255,255,255,.8);
  max-width: 42ch;
  margin-bottom: 2rem;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}
.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: .75rem;
  aspect-ratio: 1;
}
.hero-img-tile {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: rgba(255,255,255,.06);
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-img-tile:first-child {
  grid-row: span 2;
  border-radius: var(--radius-lg);
}
.hero-img-tile svg { opacity: .35; }

/* =========================================================
   Category pills strip
   ========================================================= */
.category-strip {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 1.25rem 0;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.category-strip::-webkit-scrollbar { display: none; }
.category-list {
  display: flex;
  gap: .75rem;
  padding-inline: var(--gutter);
  max-width: var(--max-width);
  margin-inline: auto;
}
.category-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .4rem;
  flex-shrink: 0;
  text-decoration: none;
  color: var(--color-text-muted);
  font-size: .78rem;
  font-weight: 600;
  transition: color .12s;
}
.category-pill:hover,
.category-pill:focus-visible { color: var(--color-brand); }
.category-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-lg);
  background: var(--color-bg);
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  transition: border-color .12s, background .12s;
}
.category-pill:hover .category-icon,
.category-pill:focus-visible .category-icon {
  border-color: var(--color-accent);
  background: #fef3c7;
}

/* =========================================================
   Product cards
   ========================================================= */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  transition: box-shadow .2s, transform .2s;
  border: 1px solid var(--color-border);
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-3px); }
}

.product-img-wrap {
  aspect-ratio: 1;
  overflow: hidden;
  background: var(--color-bg);
  position: relative;
}
.product-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .3s;
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover .product-img-wrap img { transform: scale(1.04); }
}

/* Product badges */
.product-badges {
  position: absolute;
  top: .75rem;
  left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
  pointer-events: none;
}
.badge {
  display: inline-flex;
  align-items: center;
  padding: .2rem .55rem;
  border-radius: var(--radius-pill);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-sale  { background: var(--color-sale);    color: #fff; }
.badge-new   { background: var(--color-brand);   color: #fff; }
.badge-trending { background: var(--color-accent); color: var(--color-brand); }

/* Wishlist toggle on card */
.wishlist-btn {
  position: absolute;
  top: .75rem; right: .75rem;
  background: rgba(255,255,255,.9);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  color: var(--color-text-muted);
  transition: color .12s, background .12s, border-color .12s;
}
.wishlist-btn:hover,
.wishlist-btn:focus-visible {
  color: var(--color-sale);
  border-color: var(--color-sale);
  background: #fff;
}
.wishlist-btn[aria-pressed="true"] { color: var(--color-sale); border-color: var(--color-sale); }

.product-body {
  padding: 1rem 1rem .5rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.product-brand {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: .25rem;
}
.product-name a {
  font-size: .95rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.3;
  text-decoration: none;
}
.product-name a:hover,
.product-name a:focus-visible {
  color: var(--color-brand);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  margin-top: .4rem;
  font-size: .78rem;
  color: var(--color-text-muted);
}
.stars { color: #b45309; letter-spacing: .05em; }

.product-price-row {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-top: auto;
  padding-top: .75rem;
}
.price-current {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-brand);
}
.price-original {
  font-size: .85rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-discount {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-sale);
}

.product-footer {
  padding: .75rem 1rem 1rem;
  border-top: 1px solid var(--color-border);
  margin-top: .25rem;
}
.btn-add-cart {
  width: 100%;
  padding: .6rem 1rem;
  background: var(--color-brand);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  transition: background .12s;
}
.btn-add-cart:hover,
.btn-add-cart:focus-visible { background: var(--color-brand-light); }
.btn-add-cart:active { transform: scale(.98); }

/* =========================================================
   Featured Products section
   ========================================================= */
.featured-products {
  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
}

/* =========================================================
   Deals section
   ========================================================= */
.deals-section {
  background: #fff8ed;
  border-top: 1px solid #fde68a;
  border-bottom: 1px solid #fde68a;
  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.deal-hero-card {
  background: var(--color-brand);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 380px;
  position: relative;
  grid-row: span 2;
  color: #fff;
  padding: 2rem;
}
.deal-hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, #1e3a5f 0%, #0f1f30 100%);
  z-index: 0;
}
.deal-hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 30%, rgba(245,158,11,.18), transparent 60%);
}
.deal-hero-content { position: relative; z-index: 1; }
.deal-eyebrow {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .5rem;
}
.deal-hero-card h3 {
  font-size: clamp(1.3rem, 3vw, 1.8rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -.02em;
  margin-bottom: .75rem;
}
.deal-hero-card p { color: rgba(255,255,255,.75); font-size: .9rem; margin-bottom: 1.25rem; }
.deal-timer {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.5rem;
}
.timer-unit {
  text-align: center;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
  padding: .4rem .6rem;
  min-width: 46px;
}
.timer-digits {
  font-size: 1.3rem;
  font-weight: 700;
  display: block;
  line-height: 1;
}
.timer-label {
  font-size: .6rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: rgba(255,255,255,.6);
}

/* Smaller deal cards */
.deal-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-card);
  display: flex;
  gap: 1rem;
  padding: 1.25rem;
  align-items: flex-start;
  transition: box-shadow .2s;
}
@media (prefers-reduced-motion: no-preference) {
  .deal-card:hover { box-shadow: var(--shadow-card-hover); }
}
.deal-card-img {
  width: 90px;
  height: 90px;
  border-radius: var(--radius-md);
  background: var(--color-bg);
  overflow: hidden;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.deal-card-body { flex: 1; }
.deal-card-name {
  font-size: .9rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: .2rem;
  line-height: 1.3;
}
.deal-card-name a {
  text-decoration: none;
  color: inherit;
}
.deal-card-name a:hover,
.deal-card-name a:focus-visible {
  color: var(--color-brand);
  text-decoration: underline;
}
.deal-card-prices {
  display: flex;
  align-items: baseline;
  gap: .4rem;
  margin-bottom: .5rem;
}
.deal-progress-label {
  font-size: .72rem;
  color: var(--color-text-muted);
  margin-bottom: .25rem;
}
.deal-progress {
  height: 5px;
  background: var(--color-border);
  border-radius: var(--radius-pill);
  overflow: hidden;
}
.deal-progress-bar {
  height: 100%;
  background: var(--color-accent-dark);
  border-radius: var(--radius-pill);
  transition: width .3s;
}

/* =========================================================
   Brand editorial strip
   ========================================================= */
.brand-strip {
  padding: 2rem 0;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.brand-strip-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  flex-wrap: wrap;
}
.brand-strip-heading {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  flex-shrink: 0;
  white-space: nowrap;
}
.brand-logos {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem 2.5rem;
  align-items: center;
}
.brand-logo {
  font-size: .95rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-border);
  transition: color .15s;
  text-decoration: none;
}
.brand-logo:hover,
.brand-logo:focus-visible { color: var(--color-brand); }

/* =========================================================
   Editorial section
   ========================================================= */
.editorial-section {
  padding: clamp(2.5rem, 6vw, 4.5rem) 0;
}
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 1.5rem;
}
